الكود:

<!DOCTYPE html>
<html>
<head>
<style>
/* تصميم الصندوق (البوب أب) */
.popup {
  display: none;
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  padding: 20px;
  background: #f0f0f0;
  border: 1px solid #888;
  box-shadow: 0 0 10px #000;
}
</style>
</head>
<body>

<button onclick="showPopup()">أظهر البوب أب</button>

<div id="myPopup" class="popup">
  هذا هو البوب أب
  <br><br>
  <button onclick="hidePopup()">أغلق</button>
</div>

<script>
function showPopup() {
  document.getElementById('myPopup').style.display = 'block';
}
function hidePopup() {
  document.getElementById('myPopup').style.display = 'none';
}
</script>

</body>
</html>
